procedure PhysioConfirmNewSession {
  about "Confirm a new session row and add it to the calendar"
  policy PhysioPolicy
  sheet Sessions "Sessions" { patient: Text, mobile: Phone, session_at: DateTime, therapist: Text, status: Text, injury: Text private }
  calendar Rooms "Rooms"
  trigger when new row r in Sessions

