  let ev = book Rooms { title: "{r.patient}", at: r.session_at, length: 45 minutes }
  let m = draft sms to r.mobile: "Hi {r.patient}, your session with the physio is confirmed."
  let ok = request approval of m from owner timeout 1 day else skip
  send ok
  update r set status = "confirmed"
}
