procedure PhysioChannelList {
  about "Tell the patient their session is cancelled"
  policy PhysioPolicy
  sheet Cancellations "Cancellations" { session_id: Text, patient: Text, mobile: Phone, event_id: Text }
  calendar Rooms "Rooms"
  trigger when new row r in Cancellations

  let ev = book Rooms { title: r.patient, at: r.mobile, length: 45 minutes }
