procedure DrivingDailySummary {
  about "Tell the owner how many learners were passed recently"
  policy DrivingPolicy
  sheet Learners "Learners" { learner: Text, phone: Phone, lessons_left: Number, test_date: Date, status: Text, license_no: Text private }
  sheet Stats "Stats" { day: Date, passed: Number }
  trigger every month on day 1 at 09:00

  let all = fetch Learners
  let recent = filter all where status == "passed" and days_between(test_date, today()) <= 31 and days_between(test_date, today()) >= 0
  let n = summarize count of recent
  append Stats { day: today(), passed: n }
  notify owner "Passed learners today: {n}"
}
