procedure HardwareRefunds {
  about "Handle returns within limits"
  policy HardwarePolicy
  sheet Returns "Returns" { return_no: Text, customer: Text, phone: Phone, amount: Money, bought: Date, opened: Bool, status: Text }
  trigger when new row r in Returns

  if r.opened {
    notify owner "Opened return {r.return_no} for {r.customer}. Please handle it."
    stop "opened returns go to owner"
  }
  if days_between(r.bought, today()) > 30 {
    notify owner "Old return {r.return_no} for {r.customer}. Please handle it."
    stop "old returns go to owner"
  }
  if r.amount > $100 {
    notify owner "Refund of {r.amount} for return {r.return_no} for {r.customer} goes to owner."
    stop "over $100 goes to owner"
  }
  refund r.amount for r.return_no reason "refund request", ask owner first timeout 1 day else stop "refund not approved"
  let m = draft sms to r.phone: "Hi {r.customer}, your refund of {r.amount} has been issued."
  let ok = request approval of m from owner timeout 1 day else stop "message not approved"
  send ok
  update r set status = "refunded"
}
```

