procedure EscapeConfirmNewBooking {
  about "Confirm a new booking and add it to the calendar"
  policy EscapePolicy
  sheet Bookings "Bookings" { group_name: Text, leader_phone: Phone, slot: DateTime, players: Number, status: Text, waiver_notes: Text private }
  calendar Rooms "Rooms"
  trigger when new row r in Bookings

  if r.players < 2 {
    notify owner "Short booking for {r.group_name} at {r.slot}. Please handle it."
    stop "short booking goes to owner"
  }
  let ev = book Rooms { title: "{r.group_name}", at: r.slot, length: 60 minutes }
  let ok = request approval of f"Hi {r.leader_phone default 'there'}, confirm the booking for {r.group_name} at {r.slot}."
  send ok
  update r set status = "confirmed"
}
