procedure MoveRefunds {
  about "Handle refund requests within limits"
  policy MovePolicy
  sheet MoveCancellations "MoveCancellations" { job: Text, customer: Text, phone: Phone, deposit: Money, move_date: Date }
  trigger when new row r in MoveCancellations

  if r.move_date == today() + 7 days or r.move_date == today() + 6 days or r.move_date == today() + 5 days or r.move_date == today() + 4 days or r.move_date == today() + 3 days or r.move_date == today() + 2 days or r.move_date == today() + 1 days {
    notify owner "Refund request for {r.customer} is for a move date of {r.move_date}, which is less than 7 days away."
    stop "outside refund window"
  }
  if r.deposit > $200 {
    notify owner "Refund request for {r.customer} is {r.deposit}, over $200. Please review."
    stop "over refund limit"
  }
  let m = draft sms to r.phone: "Hi {r.customer default 'there'}, your refund of {r.deposit} has been issued."
  let ok = request approval of m from owner timeout 1 day else stop "refund not approved"
  send ok
}
