    if is_empty(r.opponent) {
      notify owner "Row {r.row} has a blank opponent."
      skip
    }
    let m = draft sms to r.player_phone: "Hi {r.player}, play with {r.opponent} tomorrow."
    let ok = request approval of m from owner timeout 1 day else skip
    send ok
  }
}
